import { ChangeDetectionStrategy, Component, ElementRef, computed, input, model, viewChildren } from '@angular/core';

// The arrow keys move through the stars the way they move through any radio group.
const ARROW_STEPS: Record<string, number> = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 };

@Component({
  selector: 'app-star-rating',
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './star-rating.component.html',
  styleUrls: ['./star-rating.component.css']
})
export class StarRatingComponent {
  readonly max = input(5);
  readonly rating = model(0);
  readonly stars = computed(() => Array.from({ length: this.max() }, (_, i) => i + 1));
  // A radio group is one Tab stop: the checked star, or the first star before anything is rated.
  readonly tabStop = computed(() => (this.rating() > 0 ? this.rating() : 1));

  private readonly starButtons = viewChildren<ElementRef<HTMLButtonElement>>('starButton');

  onRate(value: number): void {
    if (value < 1 || value > this.max()) {
      return;
    }
    // Setting a model also emits ratingChange, the event [(rating)] in the parent listens to.
    this.rating.set(value);
  }

  onKeydown(event: KeyboardEvent, star: number): void {
    const step = ARROW_STEPS[event.key];
    if (!step) {
      return;
    }
    // The arrows would otherwise scroll the page.
    event.preventDefault();
    const count = this.max();
    const next = ((star - 1 + step + count) % count) + 1;
    this.onRate(next);
    this.starButtons()[next - 1]?.nativeElement.focus();
  }
}

